import json
import boto3
import os

# Lambda function that serves as a Step Functions task handler
# Processes user document requests in a document management workflow

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(os.environ.get('DOCUMENTS_TABLE', 'user-documents'))
sfn_client = boto3.client('stepfunctions')

def lambda_handler(event, context):
    """
    Handler for document retrieval step in the workflow.
    Exposed via Lambda Function URL for direct invocation by frontend.

    Expected payload:
    {
        "document_id": "doc-xxxx",
        "user_id": "user-yyyy",
        "action": "retrieve" | "delete" | "share"
    }
    """

    # Parse request body from Function URL invocation
    if 'body' in event:
        body = json.loads(event['body']) if isinstance(event['body'], str) else event['body']
    else:
        body = event

    document_id = body.get('document_id')
    user_id = body.get('user_id')
    action = body.get('action', 'retrieve')

    if not document_id or not user_id:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'Missing required fields'})
        }

    # VULNERABILITY: No authorization check - the user_id from the request
    # is trusted directly without verifying it matches the authenticated caller.
    # Any caller can specify any user_id to access other users' documents.

    if action == 'retrieve':
        return retrieve_document(document_id, user_id)
    elif action == 'delete':
        return delete_document(document_id, user_id)
    elif action == 'share':
        return share_document(document_id, user_id, body.get('share_with'))
    else:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': f'Unknown action: {action}'})
        }


def retrieve_document(document_id, user_id):
    """Retrieve document metadata and signed URL for download."""
    response = table.get_item(
        Key={'document_id': document_id, 'owner_id': user_id}
    )

    if 'Item' not in response:
        return {
            'statusCode': 404,
            'body': json.dumps({'error': 'Document not found'})
        }

    item = response['Item']

    # Generate presigned URL for S3 download
    s3_client = boto3.client('s3')
    presigned_url = s3_client.generate_presigned_url(
        'get_object',
        Params={
            'Bucket': os.environ.get('DOCUMENTS_BUCKET', 'docs-bucket'),
            'Key': f"{user_id}/{document_id}"
        },
        ExpiresIn=3600
    )

    return {
        'statusCode': 200,
        'body': json.dumps({
            'document_id': document_id,
            'filename': item.get('filename'),
            'created_at': item.get('created_at'),
            'download_url': presigned_url
        })
    }


def delete_document(document_id, user_id):
    """Delete a document from the system."""
    table.delete_item(
        Key={'document_id': document_id, 'owner_id': user_id}
    )

    s3_client = boto3.client('s3')
    s3_client.delete_object(
        Bucket=os.environ.get('DOCUMENTS_BUCKET', 'docs-bucket'),
        Key=f"{user_id}/{document_id}"
    )

    return {
        'statusCode': 200,
        'body': json.dumps({'message': 'Document deleted successfully'})
    }


def share_document(document_id, user_id, share_with):
    """Share document with another user."""
    if not share_with:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'share_with field required'})
        }

    table.update_item(
        Key={'document_id': document_id, 'owner_id': user_id},
        UpdateExpression='SET shared_with = list_append(if_not_exists(shared_with, :empty), :new_user)',
        ExpressionAttributeValues={
            ':empty': [],
            ':new_user': [share_with]
        }
    )

    return {
        'statusCode': 200,
        'body': json.dumps({'message': f'Document shared with {share_with}'})
    }
